// RynoServer is the server API for Ryno service.
// All implementations must embed UnimplementedRynoServer
// for forward compatibility.
//
// Ryno service provides sandbox, provider, and runtime management capabilities.
//
// Conventions:
//   - This file owns the public API resource model exposed to Ryno clients.
//   - `Sandbox`, `SandboxSpec`, `SandboxStatus`, and `SandboxPhase` are gateway-owned
//     public types. Internal compute drivers must not import or return them directly.
//   - The gateway translates internal compute-driver observations into these public
//     resource messages before persisting or returning them to clients.
type RynoServer interface {
	// Check the health of the service.
	Health(context.Context, *HealthRequest) (*HealthResponse, error)
	// Return the authenticated caller identity established by the gateway.
	GetCurrentUser(context.Context, *GetCurrentUserRequest) (*GetCurrentUserResponse, error)
	// Fetch elevated live gateway runtime metadata.
	GetGatewayInfo(context.Context, *GetGatewayInfoRequest) (*GetGatewayInfoResponse, error)
	// Create a new sandbox.
	CreateSandbox(context.Context, *CreateSandboxRequest) (*SandboxResponse, error)
	// Allocate a gateway-owned staging slot for a local rootfs tar archive.
	//
	// The gateway creates a request-scoped directory inside the compute driver's
	// staging root and returns an opaque single-use token plus the absolute path
	// the client must write the archive to. The token is then passed as
	// `template.driver_config.<driver>.rootfs_tar_staging_token` on
	// CreateSandbox; callers never name a filesystem path themselves. Only a
	// client sharing the gateway's filesystem can complete the upload.
	BeginRootfsTarStaging(context.Context, *BeginRootfsTarStagingRequest) (*BeginRootfsTarStagingResponse, error)
	// Fetch a sandbox by name.
	GetSandbox(context.Context, *GetSandboxRequest) (*SandboxResponse, error)
	// List sandboxes.
	ListSandboxes(context.Context, *ListSandboxesRequest) (*ListSandboxesResponse, error)
	// Create a reusable sandbox workload template.
	CreateSandboxTemplate(context.Context, *CreateSandboxTemplateRequest) (*SandboxTemplateResponse, error)
	// Fetch a reusable sandbox workload template by name.
	GetSandboxTemplate(context.Context, *GetSandboxTemplateRequest) (*SandboxTemplateResponse, error)
	// List reusable sandbox workload templates.
	ListSandboxTemplates(context.Context, *ListSandboxTemplatesRequest) (*ListSandboxTemplatesResponse, error)
	// Delete a reusable sandbox workload template by name.
	DeleteSandboxTemplate(context.Context, *DeleteSandboxTemplateRequest) (*DeleteSandboxTemplateResponse, error)
	// List provider records attached to a sandbox.
	ListSandboxProviders(context.Context, *ListSandboxProvidersRequest) (*ListSandboxProvidersResponse, error)
	// Attach a provider record to an existing sandbox.
	AttachSandboxProvider(context.Context, *AttachSandboxProviderRequest) (*AttachSandboxProviderResponse, error)
	// Detach a provider record from an existing sandbox.
	DetachSandboxProvider(context.Context, *DetachSandboxProviderRequest) (*DetachSandboxProviderResponse, error)
	// Inspect the installed authority for one sandbox provider mutation.
	GetSandboxProviderStatus(context.Context, *GetSandboxProviderStatusRequest) (*GetSandboxProviderStatusResponse, error)
	// Delete a sandbox by name.
	DeleteSandbox(context.Context, *DeleteSandboxRequest) (*DeleteSandboxResponse, error)
	// Stop a sandbox while retaining its persistent state.
	StopSandbox(context.Context, *StopSandboxRequest) (*SandboxResponse, error)
	// Start a previously stopped sandbox.
	StartSandbox(context.Context, *StartSandboxRequest) (*SandboxResponse, error)
	// Create a short-lived SSH session for a sandbox.
	CreateSshSession(context.Context, *CreateSshSessionRequest) (*CreateSshSessionResponse, error)
	// Create or update a sandbox HTTP service endpoint for local routing.
	ExposeService(context.Context, *ExposeServiceRequest) (*ServiceEndpointResponse, error)
	// Fetch one sandbox HTTP service endpoint.
	GetService(context.Context, *GetServiceRequest) (*ServiceEndpointResponse, error)
	// List sandbox HTTP service endpoints.
	ListServices(context.Context, *ListServicesRequest) (*ListServicesResponse, error)
	// Delete one sandbox HTTP service endpoint.
	DeleteService(context.Context, *DeleteServiceRequest) (*DeleteServiceResponse, error)
	// Revoke a previously issued SSH session.
	RevokeSshSession(context.Context, *RevokeSshSessionRequest) (*RevokeSshSessionResponse, error)
	// Execute a command in a ready sandbox and stream output.
	ExecSandbox(*ExecSandboxRequest, grpc.ServerStreamingServer[ExecSandboxEvent]) error
	// Forward one CLI-side TCP connection to a loopback TCP target in a sandbox.
	ForwardTcp(grpc.BidiStreamingServer[TcpForwardFrame, TcpForwardFrame]) error
	// Execute an interactive command with bidirectional stdin/stdout streaming.
	// The first client message MUST carry an ExecSandboxInput with the start
	// variant. Subsequent messages carry stdin bytes or window resize events.
	ExecSandboxInteractive(grpc.BidiStreamingServer[ExecSandboxInput, ExecSandboxEvent]) error
	// Create a provider.
	CreateProvider(context.Context, *CreateProviderRequest) (*ProviderResponse, error)
	// Fetch a provider by name.
	GetProvider(context.Context, *GetProviderRequest) (*ProviderResponse, error)
	// List providers.
	ListProviders(context.Context, *ListProvidersRequest) (*ListProvidersResponse, error)
	// List available provider type profiles.
	ListProviderProfiles(context.Context, *ListProviderProfilesRequest) (*ListProviderProfilesResponse, error)
	// Fetch one provider type profile by id.
	GetProviderProfile(context.Context, *GetProviderProfileRequest) (*ProviderProfileResponse, error)
	// Import custom provider type profiles.
	ImportProviderProfiles(context.Context, *ImportProviderProfilesRequest) (*ImportProviderProfilesResponse, error)
	// Update an existing custom provider type profile.
	UpdateProviderProfiles(context.Context, *UpdateProviderProfilesRequest) (*UpdateProviderProfilesResponse, error)
	// Validate provider type profiles without registering them.
	LintProviderProfiles(context.Context, *LintProviderProfilesRequest) (*LintProviderProfilesResponse, error)
	// Update an existing provider by name.
	UpdateProvider(context.Context, *UpdateProviderRequest) (*ProviderResponse, error)
	// Fetch refresh status for one provider or provider credential.
	GetProviderRefreshStatus(context.Context, *GetProviderRefreshStatusRequest) (*GetProviderRefreshStatusResponse, error)
	// Configure gateway-owned refresh material for one provider credential.
	ConfigureProviderRefresh(context.Context, *ConfigureProviderRefreshRequest) (*ConfigureProviderRefreshResponse, error)
	// Record a gateway-owned refresh request for one provider credential.
	RotateProviderCredential(context.Context, *RotateProviderCredentialRequest) (*RotateProviderCredentialResponse, error)
	// Delete gateway-owned refresh configuration for one provider credential.
	DeleteProviderRefresh(context.Context, *DeleteProviderRefreshRequest) (*DeleteProviderRefreshResponse, error)
	// Delete a provider by name.
	DeleteProvider(context.Context, *DeleteProviderRequest) (*DeleteProviderResponse, error)
	// Delete a custom provider type profile by id.
	DeleteProviderProfile(context.Context, *DeleteProviderProfileRequest) (*DeleteProviderProfileResponse, error)
	// Get sandbox settings by id (called by sandbox entrypoint and poll loop).
	GetSandboxConfig(context.Context, *sandboxv1.GetSandboxConfigRequest) (*sandboxv1.GetSandboxConfigResponse, error)
	// Get gateway-global settings (read-only runtime configuration; any
	// authenticated user may read these without requiring Platform Admin).
	//
	// Scope-only (no role): scopes are granted by the IdP at token issuance,
	// orthogonal to workspace membership. Deployments that enable scope
	// enforcement configure the IdP to grant config:read (or ryno:all)
	// to all sandbox users, so this does not block least-privilege flows.
	GetGatewayConfig(context.Context, *sandboxv1.GetGatewayConfigRequest) (*sandboxv1.GetGatewayConfigResponse, error)
	// Update settings or policy at sandbox or global scope.
	UpdateConfig(context.Context, *UpdateConfigRequest) (*UpdateConfigResponse, error)
	// Get the load status of a specific policy version.
	GetSandboxPolicyStatus(context.Context, *GetSandboxPolicyStatusRequest) (*GetSandboxPolicyStatusResponse, error)
	// List policy history for a sandbox.
	ListSandboxPolicies(context.Context, *ListSandboxPoliciesRequest) (*ListSandboxPoliciesResponse, error)
	// Report policy load result (called by sandbox after reload attempt).
	ReportPolicyStatus(context.Context, *ReportPolicyStatusRequest) (*ReportPolicyStatusResponse, error)
	// Replace the gateway's observed tool server endpoint status for one sandbox.
	ReportEndpointStatus(context.Context, *ReportEndpointStatusRequest) (*ReportEndpointStatusResponse, error)
	// Report installed provider state for the current ConnectSupervisor session.
	// Replacing or losing that session invalidates its observations.
	ReportProviderReadiness(context.Context, *ReportProviderReadinessRequest) (*ReportProviderReadinessResponse, error)
	// Register startup and acknowledge an exact validated runtime configuration.
	ReportSandboxConfiguration(context.Context, *ReportSandboxConfigurationRequest) (*ReportSandboxConfigurationResponse, error)
	// Get provider environment for a sandbox (called by sandbox supervisor at startup).
	GetSandboxProviderEnvironment(context.Context, *GetSandboxProviderEnvironmentRequest) (*GetSandboxProviderEnvironmentResponse, error)
	// Exchange a stored provider subject token for an intermediate token scoped
	// to the calling supervisor's SPIFFE identity.
	ExchangeProviderSubjectToken(context.Context, *ExchangeProviderSubjectTokenRequest) (*ExchangeProviderSubjectTokenResponse, error)
	// Fetch recent sandbox logs (one-shot).
	GetSandboxLogs(context.Context, *GetSandboxLogsRequest) (*GetSandboxLogsResponse, error)
	// Push sandbox supervisor logs to the server (client-streaming).
	PushSandboxLogs(grpc.ClientStreamingServer[PushSandboxLogsRequest, PushSandboxLogsResponse]) error
	// Persistent supervisor-to-gateway session (bidirectional streaming).
	//
	// The supervisor opens this stream at startup and keeps it alive for the
	// sandbox lifetime. The gateway uses it to coordinate relay channels for
	// SSH connect, ExecSandbox, and targetable sandbox services. Raw service
	// bytes flow over RelayStream calls (separate HTTP/2 streams on the same
	// connection), not over this stream.
	ConnectSupervisor(grpc.BidiStreamingServer[SupervisorMessage, GatewayMessage]) error
	// Persist the canonical main process result before the supervisor exits.
	ReportMainProcessExit(context.Context, *ReportMainProcessExitRequest) (*ReportMainProcessExitResponse, error)
	// Confirm that foreground terminal delivery completed naturally.
	FinalizeMainProcessExit(context.Context, *FinalizeMainProcessExitRequest) (*FinalizeMainProcessExitResponse, error)
	// Raw byte relay between supervisor and gateway.
	//
	// The supervisor initiates this call after receiving a RelayOpen message
	// on its ConnectSupervisor stream. The first RelayFrame carries a
	// RelayInit with the channel_id to associate the new HTTP/2 stream with
	// the pending relay slot on the gateway. Subsequent frames carry raw bytes in either
	// direction between the gateway-side waiter (ForwardTcp / exec handler)
	// and the supervisor-side target bridge.
	//
	// This rides the same TCP+TLS+HTTP/2 connection as ConnectSupervisor —
	// no new TLS handshake, no reverse HTTP CONNECT.
	RelayStream(grpc.BidiStreamingServer[RelayFrame, RelayFrame]) error
	// Internal gateway-to-gateway relay forwarding.
	//
	// A gateway replica that receives a user request for a sandbox whose
	// supervisor session is owned by a different replica opens this stream to the
	// owner. The first frame carries PeerRelayInit; subsequent frames carry raw
	// bytes in either direction. This RPC is authenticated as a gateway peer, not
	// as a user or sandbox supervisor.
	PeerRelay(grpc.BidiStreamingServer[PeerRelayFrame, PeerRelayFrame]) error
	// Internal gateway-to-owner forwarding for supervisor-bound state.
	PeerReportProviderReadiness(context.Context, *ReportProviderReadinessRequest) (*ReportProviderReadinessResponse, error)
	PeerReportEndpointStatus(context.Context, *ReportEndpointStatusRequest) (*ReportEndpointStatusResponse, error)
	PeerGetSandboxProviderStatus(context.Context, *GetSandboxProviderStatusRequest) (*GetSandboxProviderStatusResponse, error)
	// Watch a sandbox and stream updates.
	//
	// This stream can include:
	// - Sandbox status snapshots (phase/status)
	// - Ryno server process logs correlated by sandbox_id
	// - Platform events correlated to the sandbox
	WatchSandbox(*WatchSandboxRequest, grpc.ServerStreamingServer[SandboxStreamEvent]) error
	// Submit denial analysis results from sandbox (summaries + proposed chunks).
	SubmitPolicyAnalysis(context.Context, *SubmitPolicyAnalysisRequest) (*SubmitPolicyAnalysisResponse, error)
	// Get draft policy recommendations for a sandbox.
	GetDraftPolicy(context.Context, *GetDraftPolicyRequest) (*GetDraftPolicyResponse, error)
	// Approve a single draft policy chunk (merges into active policy).
	ApproveDraftChunk(context.Context, *ApproveDraftChunkRequest) (*ApproveDraftChunkResponse, error)
	// Reject a single draft policy chunk.
	RejectDraftChunk(context.Context, *RejectDraftChunkRequest) (*RejectDraftChunkResponse, error)
	// Approve all pending draft chunks (skips security-flagged unless forced).
	ApproveAllDraftChunks(context.Context, *ApproveAllDraftChunksRequest) (*ApproveAllDraftChunksResponse, error)
	// Edit a pending draft chunk in-place (e.g. narrow allowed_ips).
	EditDraftChunk(context.Context, *EditDraftChunkRequest) (*EditDraftChunkResponse, error)
	// Reverse an approval (remove merged rule from active policy).
	UndoDraftChunk(context.Context, *UndoDraftChunkRequest) (*UndoDraftChunkResponse, error)
	// Clear all pending draft chunks for a sandbox.
	ClearDraftChunks(context.Context, *ClearDraftChunksRequest) (*ClearDraftChunksResponse, error)
	// Get decision history for a sandbox's draft policy.
	GetDraftHistory(context.Context, *GetDraftHistoryRequest) (*GetDraftHistoryResponse, error)
	// Exchange a sandbox-bootstrap credential (e.g. a Kubernetes projected
	// ServiceAccount token) for a gateway-minted JWT bound to the calling
	// sandbox's UUID. Used by the Kubernetes driver path; singleplayer
	// drivers receive the gateway JWT directly from the create-sandbox flow
	// and never call this RPC.
	IssueSandboxToken(context.Context, *IssueSandboxTokenRequest) (*IssueSandboxTokenResponse, error)
	// Renew the calling sandbox's gateway JWT. Older tokens remain valid
	// until their own expiry; deployments should keep token TTLs short to
	// bound replay exposure. The supervisor calls this from a background
	// task at ~80% of the token's lifetime; the new token is cached in
	// memory only — the on-disk bootstrap file is intentionally not
	// rewritten.
	RefreshSandboxToken(context.Context, *RefreshSandboxTokenRequest) (*RefreshSandboxTokenResponse, error)
	// Create a workspace.
	CreateWorkspace(context.Context, *CreateWorkspaceRequest) (*CreateWorkspaceResponse, error)
	// Fetch a workspace by name.
	GetWorkspace(context.Context, *GetWorkspaceRequest) (*GetWorkspaceResponse, error)
	// List workspaces.
	ListWorkspaces(context.Context, *ListWorkspacesRequest) (*ListWorkspacesResponse, error)
	// Delete a workspace by name.
	DeleteWorkspace(context.Context, *DeleteWorkspaceRequest) (*DeleteWorkspaceResponse, error)
	// Add a member to a workspace.
	AddWorkspaceMember(context.Context, *AddWorkspaceMemberRequest) (*AddWorkspaceMemberResponse, error)
	// Remove a member from a workspace.
	RemoveWorkspaceMember(context.Context, *RemoveWorkspaceMemberRequest) (*RemoveWorkspaceMemberResponse, error)
	// List members of a workspace.
	ListWorkspaceMembers(context.Context, *ListWorkspaceMembersRequest) (*ListWorkspaceMembersResponse, error)
	mustEmbedUnimplementedRynoServer()
}

